// Транслітерація
const translitMap = {
  'а':'a','б':'b','в':'v','г':'h','д':'d','е':'e','є':'ie','ж':'zh',
  'з':'z','и':'y','і':'i','ї':'i','й':'i','к':'k','л':'l','м':'m','н':'n',
  'о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'kh','ц':'ts',
  'ч':'ch','ш':'sh','щ':'shch','ь':'','ю':'iu','я':'ia',
  "'":'', '’':''
};

function translit(str) {
  return str.toLowerCase().split('')
    .map(ch => translitMap[ch] !== undefined ? translitMap[ch] : ch)
    .join('').replace(/[^a-z0-9]/g, '');
}

// Генерація пароля
function generatePassword() {
  const chars = "abcdefghijklmnopqrstuvwxyz";
  const caps = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const nums = "0123456789";
  const specs = "!@#*%^&"; 
  let pass = "";
  pass += caps[Math.floor(Math.random() * caps.length)]; 
  pass += specs[Math.floor(Math.random() * specs.length)]; 
  for (let i = 0; i < 4; i++) pass += nums[Math.floor(Math.random() * nums.length)]; 
  for (let i = 0; i < 10; i++) pass += chars[Math.floor(Math.random() * chars.length)]; 
  return pass;
}

const DOMAIN = 'example.com'; 
const TARGET_OU = 'OU=NewHires,DC=example,DC=com'; 

const leverData = $json.data || {};
const sheetData =$('Loop: Candidates Batch').item.json;

const rawFullName = (sheetData.full_name || leverData.name || 'Unknown').trim();
const fullName = rawFullName.replace(/[\(\)\*\\\,\+\<\>\;]/g, ''); 

const nameParts = fullName.split(/\s+/);
const first = nameParts[0];

let lastForLogin = '';
let lastForAD = '';

if (nameParts.length > 1) {
    lastForLogin = nameParts.slice(1).join('');
    lastForAD = nameParts.slice(1).join(' ');
} else {
    lastForLogin = first;
    lastForAD = first;
}

let personalEmail = '';
if (leverData.emails && leverData.emails.length > 0) {
     personalEmail = leverData.emails[0];
} else if (sheetData.pay_pal_id && sheetData.pay_pal_id.includes('@')) {
     personalEmail = sheetData.pay_pal_id.trim();
}

const firstLetter = translit(first).charAt(0);
const lastL = translit(lastForLogin); 

const fullLogin = `${firstLetter}.${lastL}`;
const sAMAccountName = fullLogin.substring(0, 20);
const email = `${fullLogin}@${DOMAIN}`;
const password = generatePassword(); 

const unicodePwd = Buffer.from(`"${password}"`, 'utf16le').toString('base64');

return {
  json: {
    rowNumber: sheetData.row_number || sheetData.__rowNumber,
    firstName: first,
    lastName: lastForAD,
    sAMAccountName: sAMAccountName,    
    userPrincipalName: email,          
    displayName: `${first} ${lastForAD}`.trim(),
    targetOU: TARGET_OU,
    generatedPassword: password,        
    personalEmail: personalEmail,
    unicodePwd: unicodePwd              
  }
};

// Logic for finding duplicates and appending numerical suffix to SAMAccountName up to 20 chars
const searchResults = $input.all();
const candidate =$('Format Candidate Payload').item.json;
const existingLogins = new Set();
const existingNames = new Set();
const first = candidate.firstName || '';
const last = candidate.lastName || '';
const baseLogin = candidate.sAMAccountName.toLowerCase();
const baseName = `${first} ${last}`.toLowerCase();
const candidateEmail = (candidate.personalEmail || '').toLowerCase().trim();
let requireDeletion = false;
let deleteDNs = [];
let maxSuffix = 0;

for (const res of searchResults) {
  if (res.json && Object.keys(res.json).length > 0) {
    const adLogin = (res.json.sAMAccountName || '').toLowerCase().trim();
    const adName = (res.json.cn || res.json.displayName || '').toLowerCase().trim();
    if (adLogin.startsWith(baseLogin)) {
      const remainder = adLogin.substring(baseLogin.length);
      if (remainder === '') maxSuffix = Math.max(maxSuffix, 0);
      else if (remainder.startsWith('_')) {
        const num = parseInt(remainder.substring(1), 10);
        if (!isNaN(num)) maxSuffix = Math.max(maxSuffix, num);
      }
    }
    let adEmail = res.json.postOfficeBox || '';
    if (Array.isArray(adEmail)) adEmail = adEmail[0];
    adEmail = adEmail.toLowerCase().trim();
    if (candidateEmail && adEmail === candidateEmail) {
        requireDeletion = true;
        const dn = res.json.dn || res.json.distinguishedName || res.json.DN || '';
        if (dn) deleteDNs.push(dn);
    }
    if (res.json.sAMAccountName) existingLogins.add(adLogin);
    if (res.json.cn) existingNames.add(adName);
    else if (res.json.displayName) existingNames.add(adName);
  }
}
let finalLogin = candidate.sAMAccountName;
let finalName = candidate.displayName;
let counter = 1;
let forceSuffix = false;
if (requireDeletion) {
    counter = maxSuffix + 1;
    forceSuffix = true;
}
if (forceSuffix || existingLogins.has(baseLogin) || existingNames.has(baseName)) {
  while (existingLogins.has(`${baseLogin}_${counter}`.toLowerCase()) || existingNames.has(`${baseName} ${counter}`.toLowerCase())) counter++;
  const suffix = `_${counter}`;
  const allowedLength = 20 - suffix.length; 
  finalLogin = `${candidate.sAMAccountName.substring(0, allowedLength)}${suffix}`;
  finalName = `${first} ${last} ${counter}`.trim();
}
const updatedCandidate = {
  ...candidate,
  sAMAccountName: finalLogin,
  userPrincipalName: `${finalLogin}@example.com`,
  displayName: finalName,
  requireDeletion: requireDeletion,
  deleteDNs: deleteDNs
};
const adPassword = `"${candidate.generatedPassword}"`; 
updatedCandidate.unicodePwd = Buffer.from(adPassword, 'utf16le').toString('base64');
return { json: updatedCandidate };
